METHOD_NAMES=('__init__','_identities','finish','require_witness')
_METHODS=None
_SOURCE_BINDINGS=None


def _dump(node):return ast.dump(node,include_attributes=False)


def _code_shape(code):
    return tuple(getattr(code,name) for name in ('co_code','co_names','co_varnames',
        'co_argcount','co_posonlyargcount','co_kwonlyargcount','co_flags','co_freevars','co_cellvars'))+(tuple(
            _code_shape(value) if type(value)is CodeType else value for value in code.co_consts),)


def _named_code(code,name):
    found=[value for value in code.co_consts if type(value)is CodeType and value.co_name==name]
    if len(found)!=1:raise AudioBoundary('one complete city-installation source code required: '+name)
    return found[0]


def _city_capture_tree(original_tree):
    """Exact city identities and first3BC proof; all original methods invert."""
    result=copy.deepcopy(original_tree);found=[]
    for index,node in enumerate(original_tree.body):
        if not isinstance(node,ast.ClassDef) or node.name!='DriverInstallationCapture':continue
        if found or _dump(node)!=_dump(ast.parse(EXPECTED_SOURCE_OWNERS['base']['DriverInstallationCapture']).body[0]):
            raise AudioBoundary('complete original installation capture class required')
        methods=[item for item in node.body if isinstance(item,ast.FunctionDef)]
        if tuple(item.name for item in methods)!=METHOD_NAMES:
            raise AudioBoundary('all four and only four original capture methods required')
        derived=copy.deepcopy(node);inverses={}
        for position,method in enumerate(derived.body):
            if not isinstance(method,ast.FunctionDef):continue
            expected={'__init__':(1,0,0,0,0),'finish':(0,1,1,1,0),
                '_identities':(0,0,0,0,0),'require_witness':(0,0,0,0,1)}[method.name]
            counts=[0,0,0,0,0]
            old_code=ast.parse('self.main_function.__code__').body[0].value
            new_code=ast.parse('reset.require_main_identity(main, waiting)').body[0].value
            old_first=ast.parse('main.suspensions != 1',mode='eval').body
            new_first=ast.parse('not reset.require_first_main_wait(main, waiting)',mode='eval').body
            old_sealed=ast.parse('self.reset_session.main_session.suspensions != 1',mode='eval').body
            new_sealed=ast.parse('not self.reset_session.require_first_main_wait('
                'self.reset_session.main_session, self.sealed_waiting)',mode='eval').body

            class Lift(ast.NodeTransformer):
                def visit_Name(self,item):
                    if method.name=='__init__' and item.id=='PersistentColdResetSession':
                        counts[0]+=1;item.id='CityColdResetSession'
                    elif method.name=='finish' and item.id=='BootstrapMainSession':
                        counts[1]+=1;item.id='PersistentCitySceneSession'
                    return item

                def visit_Attribute(self,item):
                    if method.name=='finish' and _dump(item)==_dump(old_code):
                        counts[2]+=1
                        return ast.copy_location(copy.deepcopy(new_code),item)
                    return self.generic_visit(item)

                def visit_Compare(self,item):
                    if method.name=='finish' and _dump(item)==_dump(old_first):
                        counts[3]+=1
                        return ast.copy_location(copy.deepcopy(new_first),item)
                    if method.name=='require_witness' and _dump(item)==_dump(old_sealed):
                        counts[4]+=1
                        return ast.copy_location(copy.deepcopy(new_sealed),item)
                    return self.generic_visit(item)

            lifted=Lift().visit(copy.deepcopy(method))
            if tuple(counts)!=expected:raise AudioBoundary('exact city installation identity sites differ')
            undo=list(counts)

            class Inverse(ast.NodeTransformer):
                def visit_Name(self,item):
                    if method.name=='__init__' and item.id=='CityColdResetSession':
                        undo[0]-=1;item.id='PersistentColdResetSession'
                    elif method.name=='finish' and item.id=='PersistentCitySceneSession':
                        undo[1]-=1;item.id='BootstrapMainSession'
                    return item

                def visit_Call(self,item):
                    if method.name=='finish' and _dump(item)==_dump(new_code):
                        undo[2]-=1
                        return ast.copy_location(copy.deepcopy(old_code),item)
                    return self.generic_visit(item)

                def visit_UnaryOp(self,item):
                    if method.name=='finish' and _dump(item)==_dump(new_first):
                        undo[3]-=1
                        return ast.copy_location(copy.deepcopy(old_first),item)
                    if method.name=='require_witness' and _dump(item)==_dump(new_sealed):
                        undo[4]-=1
                        return ast.copy_location(copy.deepcopy(old_sealed),item)
                    return self.generic_visit(item)

            inverse=Inverse().visit(copy.deepcopy(lifted))
            if any(undo) or _dump(inverse)!=_dump(method):
                raise AudioBoundary('complete city capture method inverse differs: '+method.name)
            derived.body[position]=lifted;inverses[position]=inverse
        restored_class=copy.deepcopy(derived)
        for position,inverse in inverses.items():restored_class.body[position]=inverse
        if _dump(restored_class)!=_dump(node):raise AudioBoundary('whole capture class inverse differs')
        result.body[index]=derived;found.append((index,restored_class))
    if len(found)!=1:raise AudioBoundary('one actual whole original capture class required')
    restored=copy.deepcopy(result);restored.body[found[0][0]]=found[0][1]
    if _dump(restored)!=_dump(original_tree):raise AudioBoundary('whole original installation module inverse differs')
    return ast.fix_missing_locations(result)


def _load_source_bindings(module,expected):
    tree=ast.parse(inspect.getsource(module),filename=module.__file__)
    nodes={node.name:node for node in tree.body if isinstance(node,(ast.FunctionDef,ast.ClassDef))}
    compiled=compile(tree,module.__file__,'exec',dont_inherit=True);bindings=[]
    for name,source in expected.items():
        if name not in nodes or _dump(nodes[name])!=_dump(ast.parse(source).body[0]):
            raise AudioBoundary('complete reviewed city installation dependency differs: '+name)
        actual=getattr(module,name)
        if isinstance(nodes[name],ast.ClassDef):
            if type(actual)is not type or actual.__module__!=module.__name__ or actual.__name__!=name:
                raise AudioBoundary('actual exact city installation dependency class required')
            bindings.append((module,name,actual,None,None))
            cls_code=_named_code(compiled,name)
            for method in (n for n in nodes[name].body if isinstance(n,ast.FunctionDef)):
                function=actual.__dict__.get(method.name)
                _require_function(module,function,name+'.'+method.name,_named_code(cls_code,method.name),actual)
                bindings.append((actual,method.name,function,function.__code__,module))
        else:
            _require_function(module,actual,name,_named_code(compiled,name))
            bindings.append((module,name,actual,actual.__code__,module))
    return tree,bindings


def _require_function(module,function,qualname,code,owner_class=None):
    closure_ok=(function.__closure__ is None if type(function)is FunctionType else False)
    if type(function)is FunctionType and code.co_freevars==('__class__',):
        closure_ok=(owner_class is not None and function.__closure__ is not None
            and len(function.__closure__)==1 and function.__closure__[0].cell_contents is owner_class)
    if (type(function)is not FunctionType or function.__module__!=module.__name__
            or function.__qualname__!=qualname or function.__globals__ is not vars(module)
            or not closure_ok or _code_shape(function.__code__)!=_code_shape(code)):
        raise AudioBoundary('actual complete city installation callable/source identity required: '+qualname)


def _make_method_views():
    from tools.high_level_main_flows import city_cold_reset,city_scene_steps
    from tools.high_level_scene_flows import source_artifact_cache
    modules=dict(base=_base,cold=city_cold_reset,city=city_scene_steps,
        artifacts=source_artifact_cache)
    if set(EXPECTED_SOURCE_OWNERS)!=set(modules):raise AudioBoundary('exact finite city installation source families required')
    bindings=[];trees={}
    for group,module in modules.items():
        trees[group],records=_load_source_bindings(module,EXPECTED_SOURCE_OWNERS[group])
        bindings.extend(records)
    for name in ('read_source_text','get_source_artifacts'):
        original=getattr(source_artifact_cache,name)
        if getattr(city_scene_steps,name)is not original:
            raise AudioBoundary('city source artifact alias differs from its exact owner: '+name)
        # Both the defining module and this importing alias remain in the
        # ordinary runtime source-binding identity/code/globals guard.
        bindings.append((city_scene_steps,name,original,original.__code__,source_artifact_cache))
    derived=compile(_city_capture_tree(trees['base']),_base.__file__,'exec',dont_inherit=True)
    cls_code=_named_code(derived,'DriverInstallationCapture')
    namespace=dict(vars(_base))
    if any(name in namespace for name in ('CityColdResetSession','PersistentCitySceneSession')):
        raise AudioBoundary('private city capture identities must not shadow original names')
    namespace.update(CityColdResetSession=city_cold_reset.CityColdResetSession,
        PersistentCitySceneSession=city_scene_steps.PersistentCitySceneSession)
    views={}
    for name in METHOD_NAMES:
        original=_base.DriverInstallationCapture.__dict__[name]
        view=FunctionType(_named_code(cls_code,name),namespace,name,original.__defaults__,None)
        view.__kwdefaults__=original.__kwdefaults__;view.__annotations__=dict(original.__annotations__)
        if view.__closure__ is not None or inspect.isgeneratorfunction(view):
            raise AudioBoundary('city installation retains exact ordinary original capture methods')
        views[name]=view
    return views,tuple(bindings)


def _require_source_bindings(capture):
    if type(capture)is not CityDriverInstallationCapture:
        raise AudioBoundary('one exact city-cold installation capture required')
    if _METHODS is None or _SOURCE_BINDINGS is None:raise AudioBoundary('city installation source views are unbound')
    for owner,name,original,code,module in _SOURCE_BINDINGS:
        if getattr(owner,name)is not original or (code is not None and
                (original.__code__ is not code or original.__globals__ is not vars(module))):
            raise AudioBoundary('city installation original source owner was rebound: '+name)


class CityDriverInstallationCapture:
    """The original exact installation algorithm, selected before city-cold resume.

    Its result is the original exact DriverInstallationWitness. Thus the old
    DriverInstalledAuthority, AudioEntryAuthority and platform-handoff guards
    remain fully unchanged; this class owns no compatible-any witness path.
    """
    def __init__(self,sound,control,source,*,reset_session):
        _require_source_bindings(self)
        _METHODS['__init__'](self,sound,control,source,reset_session=reset_session)

    def _identities(self):
        _require_source_bindings(self)
        return _METHODS['_identities'](self)

    def finish(self,waiting):
        _require_source_bindings(self)
        return _METHODS['finish'](self,waiting)

    def require_witness(self,witness,sound,control):
        _require_source_bindings(self)
        return _METHODS['require_witness'](self,witness,sound,control)


